def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_me, last_opp = history[-1]

    opp_d = 0
    opp_c = 0
    my_d = 0
    for me, opp in history:
        if opp == 'D':
            opp_d += 1
        else:
            opp_c += 1
        if me == 'D':
            my_d += 1

    # If the opponent has defected the entire observed match, stop being nice.
    if n >= 2 and opp_c == 0:
        return 'D'

    # Recent opponent hostility.
    rec_op_d = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            rec_op_d += 1

    # Trailing defection streaks, used for finite punishment.
    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    # Count how many straight rounds we have just cooperated while they defected.
    cd_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C' and history[i][1] == 'D':
            cd_streak += 1
        else:
            break

    # Count opponent cooperation streak.
    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_streak += 1
        else:
            break

    # Evidence from transitions: did our defection get punished or tolerated?
    recent_retal = 0
    recent_soft = 0
    start2 = n - 21
    if start2 < 0:
        start2 = 0
    for i in range(start2, n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'D':
                recent_retal += 1
            else:
                recent_soft += 1

    remaining = 100 - n

    # Very late exploitation.  Against responsive nice opponents this is close to
    # neutral, while it extracts clear value from unconditionally cooperative ones.
    if remaining <= 2 and opp_d <= 12 and opp_c >= opp_d:
        return 'D'

    # If the opponent is consistently hostile, do not keep opening the door.
    hostile = (rec_op_d >= 8) or (opp_d > 20) or (n > 40 and opp_d * 2 > n)

    if last_opp == 'D':
        if hostile or opp_c == 0:
            return 'D'

        # If we just tried to forgive and they defected, give one more chance only
        # when their overall record is cooperative.  This breaks TFT-like cycles
        # without staying open against exploitative opponents.
        if last_me == 'C' and cd_streak <= 1 and opp_d <= 15 and opp_c >= opp_d:
            return 'C'

        # After enough punishment, offer cooperation again if they are not hostile.
        if opp_d_streak >= 2 and my_d_streak >= 2:
            if opp_c >= opp_d or opp_d <= 6:
                return 'C'

        # For longer punishment episodes, reset once both sides have defected enough.
        if opp_d_streak >= 4 and my_d_streak >= 4 and opp_c >= opp_d:
            return 'C'

        return 'D'

    # Opponent cooperated last round.

    # Exploit opponents that have never defected after a short cooperation test.
    if opp_d == 0 and n >= 4:
        return 'D'

    # If we just defected and the opponent still cooperated, and they have shown
    # more tolerance than punishment recently, continue exploiting.
    if last_me == 'D' and recent_soft > recent_retal:
        if opp_d <= 3 or opp_c >= 3 * max(opp_d, 1):
            return 'D'

    # Otherwise maintain cooperative defaults, avoiding accidental mutual-D locks.
    return 'C'
